INSERT INTO jg_grade_rules (id, school_id, version_label, grade_code, name, level, track, system_name, no_fail, total_min, exam_min, stage_names, rule_text, certificate_name, next_grade_name) VALUES (md5('jg|2024-2025|10')::uuid, NULL, '2024-2025', 10, 'الأول الثانوي', 'secondary', NULL, 'نظام الفصلين الدراسيين (الثانوي)', false, 0.5, 0.4, '["الفصل الأول","الفصل الثاني",null]'::jsonb, 'تُحسب الدرجة النهائية من مجموع الفصلين. يُشترط للنجاح: 40% من مجموع درجات امتحاني نهاية الفصلين، و50% من الدرجة المقررة للمادة. امتحان الدور الثاني يحل محل امتحاني نهاية الفصلين (نظري فقط في المواد العملية) ويحتفظ الطالب بدرجات أعمال الفصلين.', NULL, 'الثاني الثانوي (علمي أو أدبي)') ON CONFLICT (id) DO NOTHING;
